style.css:
@-moz-document domain("mstdn.social"), domain("mastodon.social") {
html {
  background-color: #0a0a0a !important;
  /* Entirely CSS-generated wallpaper: no image URLs or encoded assets. */
  /* Thin pale-green grid at 40px intervals, plus faint 4px CRT scan lines. */
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
  color-scheme: dark !important;
}

/* Override the site theme on the root and themed body. */
html, html body, [data-color-scheme] {
  --color-text-primary: #d9ffe6 !important;
  --color-text-secondary: #9ee5b6 !important;
  --color-text-tertiary: #70b68b !important;
  --color-text-disabled: #81c99a !important;
  --color-text-inverted: #021108 !important;
  --color-text-brand: #7fffac !important;
  --color-text-brand-soft: #b7ffce !important;
  --color-text-status-links: #7fffac !important;
  --color-text-on-brand-base: #001b09 !important;
  --color-text-brand-on-inverted: #021108 !important;
  --color-text-bookmark-highlight: #00ff66 !important;
  --color-text-favourite-highlight: #7fffac !important;
  --color-bg-desktop: transparent !important;
  --color-bg-primary: rgba(2,23,11,.97) !important;
  --color-bg-secondary: rgba(2,26,12,.82) !important;
  --color-bg-tertiary: rgba(6,46,22,.84) !important;
  --color-bg-highlight: rgba(16,104,45,.47) !important;
  --color-bg-brand-base: #00e85c !important;
  --color-bg-brand-base-hover: #38ff87 !important;
  --color-bg-brand-soft: rgba(12,91,39,.56) !important;
  --color-bg-brand-softest: rgba(37,255,110,.14) !important;
  --color-bg-disabled: rgba(4,43,20,.95) !important;
  --color-bg-inverted: #d9ffe6 !important;
  --color-border-primary: rgba(32,243,107,.18) !important;
  --color-border-column: rgba(28,240,102,.36) !important;
  --color-border-input: rgba(28,240,102,.36) !important;
  --color-border-strong: rgba(45,255,118,.50) !important;
  --color-border-brand: #00ff66 !important;
  --color-border-brand-soft: rgba(28,240,102,.36) !important;
  --color-outline: #00ff66 !important;
  --color-highlight: #7fffac !important;
}

html, body, button, input, textarea, select, option, [contenteditable="true"],
.status__content, .detailed-status, .simple_form, .compose-form {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}

/* Canvas and text */
html body, #mastodon, .app-body, .ui, .columns-area, .columns-area__panels,
.columns-area__panels__main, .layout-single-column, .layout-multiple-columns {
  background-color: transparent !important;
  color: #d9ffe6 !important;
}
::selection { background: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible,
textarea:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
* { scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18); scrollbar-width: thin; }
input[type="checkbox"], input[type="radio"] { accent-color: #00e85c !important; }
a { text-decoration-color: rgba(45,255,118,.50); }
a:hover { text-decoration-color: #00ff66; }

/* Side rails and fixed navigation */
.columns-area__panels__pane__inner, .drawer__inner {
  background-color: rgba(2,24,13,.43) !important;
  background-image: linear-gradient(145deg, rgba(13,92,47,.35) 0%, rgba(4,47,25,.28) 40%, rgba(1,19,11,.59) 100%) !important;
  border: 1px solid rgba(67,255,134,.65) !important;
  border-radius: 19px !important;
  box-shadow: inset 0 1px 0 rgba(168,255,190,.19), 0 0 24px rgba(0,225,88,.13) !important;
  -webkit-backdrop-filter: blur(26px) saturate(150%) !important;
  backdrop-filter: blur(26px) saturate(150%) !important;
}
.navigation-panel, .navigation-panel__menu, .drawer__header {
  background-color: transparent !important;
}
.ui__navigation-bar, .column-header, .column-header__collapsible-inner,
.tabs-bar__wrapper, .explore__search-header, .notification__filter-bar {
  background-color: rgba(1,20,9,.58) !important;
  color: #d9ffe6 !important;
  border-color: rgba(24,241,106,.22) !important;
  -webkit-backdrop-filter: blur(11px) saturate(125%) !important;
  backdrop-filter: blur(11px) saturate(125%) !important;
}
.columns-area__panels__pane--overlay .columns-area__panels__pane__inner,
.ui__navigation-bar__items {
  background-color: rgba(2,23,11,.97) !important;
}
.logo, .logo--wordmark, .navigation-panel__logo svg, .column-link--logo svg {
  color: #7fffac !important;
  filter: drop-shadow(0 0 5px rgba(0,255,102,.76)) drop-shadow(0 0 13px rgba(0,225,88,.45)) !important;
}

/* Timelines, Explore cards, profile details and other reading surfaces */
.column {
  background-color: rgba(1,22,10,.75) !important;
  border-color: rgba(28,240,102,.36) !important;
}
.column > .scrollable { background-color: transparent !important; }
.status, .detailed-status, .status__wrapper, .account, .trends__item,
.notification-group, .notification-ungrouped, .account-header, .account-fields {
  border-color: rgba(32,243,107,.18) !important;
}
.status-card, .account-card, .explore-suggestions-card, .server-banner,
.card__bar, .nothing-here, .column-footer,
.sign-in-banner, .account__domain-pill, .status__quote,
.content-warning, .column-inline-form, .report-card, .simple_form fieldset,
.notification-group__embedded-status {
  background-color: rgba(3,30,14,.75) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #d9ffe6 !important;
}
.status__wrapper-direct, .detailed-status__wrapper-direct, .notification-group--unread,
.notification-ungrouped--unread {
  background-color: rgba(4,54,27,.58) !important;
}
.status__content, .display-name strong, .status-card__title, .account__display-name {
  color: #d9ffe6 !important;
}
.status__relative-time, .display-name__account, .detailed-status__meta,
.status-card__description, .navigation-panel__legal {
  color: #9ee5b6 !important;
}
.status__content blockquote, .status__content pre, .status__content code,
.detailed-status blockquote {
  background-color: rgba(4,45,22,.44) !important;
  border-color: #00e85c !important;
}

/* Hover feedback on controls and row edges keeps photos and video clear. */
.column-link:hover, .column-link.active, .column-link[aria-current="page"],
.ui__navigation-bar__item:hover, .ui__navigation-bar__item[aria-current="page"],
.tabs-bar__wrapper a:hover, .tabs-bar__wrapper a[aria-current="page"],
.column-header__button:hover, .column-header__back-button:hover, .icon-button:hover,
.dropdown-menu__item:hover, .dropdown-menu__item--highlighted,
.privacy-dropdown__option:hover, .search__popout__menu__item:hover,
.column-select__option--is-focused {
  background-color: rgba(17,117,53,.40) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76), 0 0 10px rgba(0,255,102,.09) !important;
}
.status__wrapper:hover, .status-card:hover, .account-card:hover, .trends__item:hover,
.explore-suggestions-card:hover {
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76) !important;
}

/* Compose, search, preferences and buttons */
.compose-panel, .compose-standalone, .compose-form__highlightable, .compose-form__footer,
.compose-form__poll, .compose-form__uploads {
  background-color: rgba(3,40,21,.45) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #d9ffe6 !important;
}
.search__input, .compose-form textarea, .simple_form input[type="text"],
.simple_form input[type="email"], .simple_form input[type="password"],
.simple_form input[type="url"], .simple_form input[type="number"],
.simple_form textarea, .simple_form select, .column-select__control,
input[type="search"], .report-dialog-modal__textarea {
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #d9ffe6 !important;
  caret-color: #00ff66 !important;
}
input::placeholder, textarea::placeholder { color: #9ee5b6 !important; opacity: 1 !important; }
select option { background-color: #03190b !important; color: #d9ffe6 !important; }
.button-secondary, .link-button {
  background-color: rgba(4,57,26,.88) !important;
  color: #d9ffe6 !important;
  border-color: rgba(43,255,115,.44) !important;
}
.button-secondary:hover, .link-button:hover {
  background-color: rgba(14,92,43,.63) !important;
  color: #effff4 !important;
}
.button:focus-visible, .button:hover, .button-secondary:hover {
  box-shadow: 0 0 10px rgba(0,255,102,.35) !important;
}

/* Dense glass surfaces for readable popovers and dialogs */
.dropdown-menu, .privacy-dropdown__dropdown, .language-dropdown__dropdown,
.visibility-dropdown__dropdown, .search__popout,
.column-select__menu, .autosuggest-textarea__suggestions, .emoji-picker-dropdown__menu,
.emoji-mart, .account__domain-pill__popout, .dialog-modal, .dialog-modal__popout,
.boost-modal, .report-dialog-modal, .report-modal, .modal-layout, .compare-history-modal,
.safety-action-modal__top, .safety-action-modal__bottom, .interaction-modal, .actions-modal,
.hover-card {
  background-color: rgba(2,23,11,.97) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: 0 9px 30px rgba(0,0,0,.19), 0 0 10px rgba(0,255,102,.09) !important;
}
.dropdown-menu__item, .privacy-dropdown__option, .search__popout__menu__item {
  color: inherit;
}
.dropdown-menu__item--dangerous { color: var(--color-text-error) !important; }
.info-tooltip--solid {
  background-color: rgba(1,20,10,.97) !important;
  color: #d9ffe6 !important;
}
}
